(function(){
const COLORS={work:'#ff893f',sleep:'#8b70ff',personal:'#10c9c1',commute:'#318de7',chores:'#f34fa4',pause:'#a7b9c9',vacation:'#ffce48',rest:'#10c9c1',unset:'#20364a'};
const fmt=n=>`${Math.floor(Math.max(0,n)/60)} h ${String(Math.round(Math.max(0,n)%60)).padStart(2,'0')}`;
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateOf=s=>new Date(s+'T12:00:00');
const sum=(arr,k)=>arr.reduce((n,x)=>n+(x[k]||0),0);
function parts(r){let m=nxLifeRecord(r);return [{k:'sleep',v:m.sleep},{k:'commute',v:m.commute},{k:'work',v:m.work},{k:'pause',v:r.type==='work'?Number(r.pause||0):0},{k:'chores',v:m.chores},{k:'personal',v:Math.max(0,1440-m.sleep-m.commute-m.work-(r.type==='work'?Number(r.pause||0):0)-m.chores)}]}
function timeline(r,descending=false){let p=parts(r);if(descending)p=p.slice().sort((a,b)=>b.v-a.v);else p=p.slice().sort((a,b)=>a.v-b.v);let total=sum(p,'v');return `<div class="life-timeline">${p.filter(x=>x.v>0).map(x=>`<span title="${x.k}: ${fmt(x.v)}" style="background:${COLORS[x.k]};flex:${x.v}"></span>`).join('')}${total<1440?`<span style="background:${COLORS.unset};flex:${1440-total}"></span>`:''}</div>`}
function typeColor(r){return COLORS[r?.type||'unset']}
window.nxLifeRender=function(){let data=nxLifeData(),r=data[nxLifeDate]||{type:'work',start:'08:30',end:'18:15',pause:'',sleep:'',commute:'',chores:''};let yr=+nxLifeDate.slice(0,4),entries=Object.entries(data).filter(([k])=>k.startsWith(yr+'-'));let totals={work:0,sleep:0,commute:0,chores:0,pause:0,personal:0},month=Array.from({length:12},()=>({work:0,sleep:0,personal:0,commute:0,pause:0,chores:0}));let workdays=[];
entries.forEach(([d,v])=>{let p=parts(v);p.forEach(x=>totals[x.k]+=x.v);let mm=month[+d.slice(5,7)-1];if(mm){mm.work+=p.find(x=>x.k==='work').v;mm.sleep+=p.find(x=>x.k==='sleep').v;mm.personal+=p.find(x=>x.k==='personal').v;mm.commute+=p.find(x=>x.k==='commute').v;mm.pause+=p.find(x=>x.k==='pause').v;mm.chores+=p.find(x=>x.k==='chores').v}if(v.type==='work')workdays.push({date:d,minutes:nxLifeRecord(v).work})});
let first=new Date(yr,0,1),firstMon=new Date(first);firstMon.setDate(first.getDate()-(first.getDay()+6)%7);
let last=new Date(yr,11,31),lastSun=new Date(last);lastSun.setDate(last.getDate()+(7-last.getDay())%7);
let weekCount=Math.round((lastSun-firstMon)/604800000)+1;
let weeks='';let monthGroups=[];for(let wi=0;wi<weekCount;wi++){let wd=new Date(firstMon);wd.setDate(firstMon.getDate()+wi*7+3);let mi=wd.getFullYear()<yr?0:wd.getFullYear()>yr?11:wd.getMonth();monthGroups.push(mi)}let monthNames=['Janv','Févr','Mars','Avr','Mai','Juin','Juil','Août','Sept','Oct','Nov','Déc'];for(let w=0;w<weekCount;w++){let d=new Date(firstMon);d.setDate(firstMon.getDate()+w*7);let th=new Date(d);th.setDate(th.getDate()+3);let jan4=new Date(th.getFullYear(),0,4);let isoMonday=new Date(jan4);isoMonday.setDate(jan4.getDate()-(jan4.getDay()+6)%7);let wn=1+Math.round((d-isoMonday)/604800000);let cells='';for(let day=0;day<7;day++){let x=new Date(d);x.setDate(d.getDate()+day);let key=iso(x),inYear=x.getFullYear()===yr;cells+=`<button type="button" class="life-cell ${key===nxLifeDate?'selected':''}" title="${key}" aria-label="Modifier le ${key}" onclick="nxLifeSelect('${key}')" style="background:${inYear?typeColor(data[key]):'transparent'};opacity:${inYear?1:.15}" ${inYear?'':'disabled'}></button>`}let monthStart=w===0||monthGroups[w]!==monthGroups[w-1];let monthSpan=monthStart?monthGroups.slice(w).findIndex(x=>x!==monthGroups[w]):-1;if(monthSpan<0)monthSpan=weekCount-w;weeks+=`<div class="life-weekrow-grid">${monthStart?`<span class="life-monthtag" style="height:calc(${monthSpan} * 16px - 1px);position:relative;z-index:1">${monthNames[monthGroups[w]]}</span>`:`<span class="life-monthblank"></span>`}<span class="life-weeknum">${String(wn).padStart(2,'0')}</span>${cells}</div>`}
let p=parts(r),m=nxLifeRecord(r),nDays=entries.length,daysInYear=(new Date(yr,11,31).getDate()===31&&(new Date(yr,1,29).getMonth()===1))?366:365;let workStart=nxLifeMins(r.start),workEnd=nxLifeMins(r.end),span=workStart===null||workEnd===null?0:(workEnd-workStart+1440)%1440;
let selectedWeekStart=dateOf(nxLifeDate);selectedWeekStart.setDate(selectedWeekStart.getDate()-(selectedWeekStart.getDay()+6)%7);let weekDays=Array.from({length:7},(_,i)=>{let d=new Date(selectedWeekStart);d.setDate(d.getDate()+i);return {date:iso(d),r:data[iso(d)]}});
let view=window.nxLifeFilter||'year';let monthFilter=window.nxLifeMonth||(+nxLifeDate.slice(5,7));let visibleEntries=Object.entries(data).filter(([d])=>view==='year'?d.startsWith(yr+'-'):view==='month'?d.startsWith(yr+'-'+String(monthFilter).padStart(2,'0')+'-'):(d>=weekDays[0].date&&d<=weekDays[6].date));let filterTotals={work:0,sleep:0,commute:0,chores:0,pause:0,personal:0};visibleEntries.forEach(([,v])=>parts(v).forEach(x=>filterTotals[x.k]+=x.v));
let maxMonth=Math.max(1,...month.map(x=>x.work+x.sleep+x.personal+x.commute+x.pause+x.chores));let longest=workdays.slice().sort((a,b)=>b.minutes-a.minutes)[0],shortest=workdays.slice().sort((a,b)=>a.minutes-b.minutes)[0];
content(`<div class="life-dash"><div class="life-top"><div><div class="life-brand">Mon temps</div><div class="life-muted">Visualise et comprends comment tu utilises ton temps, jour après jour.</div></div></div>
<div class="life-filters"><label>Jour <input class="life-filter-control" type="date" value="${nxLifeDate}" onchange="nxLifeSelectFilterDay(this.value)"></label><label>Mois <select class="life-filter-control" onchange="nxLifeChangeMonth(this.value)">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${monthFilter===i+1?'selected':''}>${new Date(2026,i,1).toLocaleDateString('fr-FR',{month:'long'})}</option>`).join('')}</select></label><label>Année <select class="life-filter-control" onchange="nxLifeGoYear(this.value)">${Array.from({length:11},(_,i)=>yr-5+i).map(y=>`<option value="${y}" ${yr===y?'selected':''}>${y}</option>`).join('')}</select></label></div>
<div class="life-panels"><section class="life-panel"><div class="life-title">1. Ma journée</div><label>Date</label><input class="life-date-field" id="nxLifeDate" type="date" value="${nxLifeDate}" onchange="nxLifeSelect(this.value)"><label>Type de journée</label><div class="life-types">${[['work','Travail'],['rest','Repos'],['vacation','Vacances']].map(([v,t])=>`<button type="button" data-type="${v}" class="${r.type===v?'active':''}" onclick="nxLifeSetType('${v}')">${t}</button>`).join('')}</div><input type="hidden" id="nxLifeType" value="${r.type}"><div id="nxLifeWork" style="display:${r.type==='work'?'block':'none'}"><label>Horaires de travail</label><div class="life-time-fields"><div><label>Début</label><input class="life-time-field" id="nxLifeStart" type="time" value="${nxLifeEsc(r.start||'08:30')}"></div><div><label>Fin</label><input class="life-time-field" id="nxLifeEnd" type="time" value="${nxLifeEsc(r.end||'18:15')}"></div></div><label>Pause totale (en minutes)</label><input id="nxLifePause" type="number" min="0" max="1439" step="1" value="${r.pause??''}"><div class="life-stat" style="margin-top:12px"><div class="life-mini">💼 Temps de travail effectif</div><div class="life-value" id="nxLifePreview">${fmt(m.work)}</div><div class="life-mini" id="nxLifeAmplitude">Amplitude ${fmt(span)} · Pause ${r.pause!==undefined&&r.pause!==''?r.pause:0} min</div></div></div><label>Sommeil (heures)</label><input id="nxLifeSleep" type="number" min="0" max="24" step="0.25" value="${r.sleep??''}"><label>Trajet (minutes)</label><input id="nxLifeCommute" type="number" min="0" max="1440" step="1" value="${r.commute??''}"><label>Sport (minutes)</label><input id="nxLifeChores" type="number" min="0" max="1440" step="1" value="${r.chores??''}"><button class="life-save" onclick="nxLifeStore()">✓ ${data[nxLifeDate]?'Modifier la journée':'Enregistrer la journée'}</button><div class="life-muted" style="margin-top:10px">Les pauses sont saisies en minutes et comptées séparément du travail.</div></section>
<section class="life-panel"><div class="life-title">2. Détail du jour</div><div class="life-muted">${dateOf(nxLifeDate).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><div style="margin:15px 0 7px">${timeline(r)}</div><div class="life-hours"><span>00 h</span><span>06 h</span><span>12 h</span><span>18 h</span><span>24 h</span></div>${p.map(x=>`<div class="life-line"><span><i class="life-dot" style="background:${COLORS[x.k]}"></i>${({work:'Travail',sleep:'Sommeil',commute:'Trajets',chores:'Sport',pause:'Pause',personal:'Temps personnel'})[x.k]}</span><b>${fmt(x.v)}</b></div>`).join('')}</section>
<section class="life-panel"><div class="life-title">3. Ma semaine</div><div class="life-muted">Du ${weekDays[0].date} au ${weekDays[6].date}</div>${weekDays.map(x=>`<div class="life-weekrow" onclick="nxLifeSelect('${x.date}')" role="button" tabindex="0"><span class="life-weekday">${dateOf(x.date).toLocaleDateString('fr-FR',{weekday:'short',day:'numeric'})}</span>${x.r?timeline(x.r,true):'<div class="life-timeline" style="flex:1;background:#1a3448"></div>'}<span class="life-workhours">${x.r?fmt(nxLifeRecord(x.r).work):'—'}</span></div>`).join('')}<div class="life-legend">${[['work','Travail'],['sleep','Sommeil'],['pause','Pause'],['commute','Trajets'],['chores','Sport'],['personal','Temps personnel']].map(([k,t])=>[k,t,weekDays.reduce((total,d)=>total+(d.r?(parts(d.r).find(x=>x.k===k)?.v||0):0),0)]).sort((a,b)=>b[2]-a[2]).map(([k,t,v])=>`<span><i class="life-dot" style="background:${COLORS[k]}"></i>${t}</span>`).join('')}</div></section>
<section class="life-panel"><div class="life-title">4. Mon mois</div><div class="life-muted">Comparaison mensuelle · ${yr}</div><div class="life-compare">${month.map(x=>`<div>${[['work',x.work+x.pause],['sleep',x.sleep],['personal',x.personal],['chores',x.chores],['commute',x.commute]].sort((a,b)=>a[1]-b[1]).map(([k,v])=>`<span title="${k}: ${fmt(v)}" style="background:${COLORS[k]};height:${v/maxMonth*100}%"></span>`).join('')}</div>`).join('')}</div><div class="life-compare-labels">${'J F M A M J J A S O N D'.split(' ').map(x=>`<span>${x}</span>`).join('')}</div><div class="life-legend">${[['work','Travail (pauses incluses)',month[monthFilter-1].work+month[monthFilter-1].pause],['sleep','Sommeil',month[monthFilter-1].sleep],['personal','Temps personnel',month[monthFilter-1].personal],['chores','Sport',month[monthFilter-1].chores],['commute','Trajets',month[monthFilter-1].commute]].sort((a,b)=>b[2]-a[2]).map(([k,t,v])=>`<span><i class="life-dot" style="background:${COLORS[k]}"></i>${t}</span>`).join('')}</div></div></section>
<div class="life-section-spacer" aria-hidden="true" style="height:12px;min-height:12px;display:block;grid-column:1/-1;"></div><section class="life-panel"><div class="life-title">5. Mon bilan</div><div class="life-muted">${view==='day'?'Bilan de la semaine':view==='month'?'Bilan du mois':'Bilan de l’année'}</div><div class="life-metrics">${[['work','💼','Travail'],['sleep','🛏','Sommeil'],['personal','♥','Temps personnel'],['chores','🏃','Sport'],['commute','🚙','Trajets'],['pause','☕','Pauses']].map(([k,ic,t])=>`<div class="life-metric"><div class="life-mini">${ic} ${t}</div><strong style="color:${COLORS[k]}">${fmt(filterTotals[k])}</strong><div class="life-mini">${(filterTotals[k]/Math.max(1,visibleEntries.length*1440)*100).toFixed(1)} %</div></div>`).join('')}</div><div class="life-stack">${Object.entries(filterTotals).filter(([,v])=>v>0).sort((a,b)=>a[1]-b[1]).map(([k,v])=>`<div class="life-bar" style="background:${COLORS[k]};width:${v/Math.max(1,visibleEntries.length*1440)*100}%"></div>`).join('')}</div><div class="life-muted">${visibleEntries.length} journée(s) enregistrée(s) pour la période sélectionnée. Les jours non saisis sont exclus.</div></section>
<div class="life-section-spacer" aria-hidden="true" style="height:12px;min-height:12px;display:block;grid-column:1/-1;"></div><section class="life-panel"><div class="life-title">6. Mon année en un coup d'œil</div><div class="life-muted">${daysInYear} jours · ${weekCount} lignes de semaines · clique sur une case pour modifier la journée</div><div class="life-heat"><div class="life-weekrow-grid life-heat-header"><span></span><span></span>${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<span>${x}</span>`).join('')}</div>${weeks}</div><div class="life-legend">${[['work','Travail'],['rest','Repos'],['vacation','Vacances'],['unset','Non renseigné']].map(([k,t])=>`<span><i class="life-dot" style="background:${COLORS[k]}"></i>${t}</span>`).join('')}</div></section></div></div>`);
const updatePreview=()=>{let a=nxLifeMins(document.getElementById('nxLifeStart').value),b=nxLifeMins(document.getElementById('nxLifeEnd').value),pause=Number(document.getElementById('nxLifePause').value),span=a===null||b===null?0:(b-a+1440)%1440,ok=a!==null&&b!==null&&a!==b&&Number.isInteger(pause)&&pause>=0&&pause<=span;document.getElementById('nxLifePreview').textContent=ok?fmt(span-pause):'Horaires invalides';document.getElementById('nxLifeAmplitude').textContent=ok?`Amplitude ${fmt(span)} · Pause ${pause} min`:'Vérifie les horaires et la pause'};
['nxLifeStart','nxLifeEnd','nxLifePause'].forEach(id=>document.getElementById(id)?.addEventListener('input',updatePreview));
};
window.nxLifeChangeFilter=function(v){window.nxLifeFilter=v;nxLifeRender()};
window.nxLifeSelectFilterDay=function(v){window.nxLifeFilter='day';nxLifeSelect(v)};
window.nxLifeChangeMonth=function(v){window.nxLifeMonth=+v;window.nxLifeFilter='month';nxLifeRender()};
window.nxLifeGoYear=function(v){window.nxLifeFilter='year';let d=dateOf(nxLifeDate);d.setFullYear(+v);nxLifeSelect(iso(d))};
window.nxLifeSetType=function(t){document.getElementById('nxLifeType').value=t;document.getElementById('nxLifeWork').style.display=t==='work'?'block':'none';document.querySelectorAll('.life-types button').forEach(b=>b.classList.toggle('active',b.dataset.type===t))};
window.nxLifeYear=function(n){let d=dateOf(nxLifeDate);d.setFullYear(d.getFullYear()+n);nxLifeSelect(iso(d))};
window.nxLifeStore=function(){let get=id=>document.getElementById(id).value,type=get('nxLifeType'),start=get('nxLifeStart'),end=get('nxLifeEnd'),pause=Number(get('nxLifePause')),sleep=Number(get('nxLifeSleep')),commute=Number(get('nxLifeCommute')),chores=Number(get('nxLifeChores'));
if(![pause,sleep,commute,chores].every(Number.isFinite)||pause<0||!Number.isInteger(pause)||sleep<0||sleep>24||commute<0||chores<0||!Number.isInteger(commute)||!Number.isInteger(chores)){toast('Vérifie les durées saisies');return}
if(type==='work'){let a=nxLifeMins(start),b=nxLifeMins(end);if(a===null||b===null||a===b||pause>(b-a+1440)%1440){toast('Horaires ou pause invalides');return}}
let r={type,start,end,pause:type==='work'?pause:0,sleep,commute,chores};let p=parts(r);if(sum(p,'v')>1440.001){toast('Le total dépasse 24 h');return}let data=nxLifeData();data[nxLifeDate]=r;nxLifeSaveData(data);nxLifeRender();toast('Journée enregistrée')};
})();

/* NEXO 2.8.1 — module Mindset avec styles indépendants, calendrier annuel calqué sur Mon temps */
const NX_MINDSET_KEY='nexoMindsetDailyStatus_v1';
let nxMindsetYear=new Date().getFullYear();
let nxMindsetSelected=(new Date()).getFullYear()+'-'+String((new Date()).getMonth()+1).padStart(2,'0')+'-'+String((new Date()).getDate()).padStart(2,'0');
function nxMindsetRead(){try{const v=JSON.parse(localStorage.getItem(NX_MINDSET_KEY)||'{}');return v&&typeof v==='object'?v:{}}catch(e){return {}}}
function nxMindsetSave(data){try{localStorage.setItem(NX_MINDSET_KEY,JSON.stringify(data))}catch(e){if(typeof toast==='function')toast('Impossible d’enregistrer le statut')}}
function nxMindsetIso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function nxMindsetStatusName(v){return v==='good'?'Bien':v==='medium'?'Moyen':v==='bad'?'Mauvais':'Non renseigné'}
function nxMindsetColor(v){return v==='good'?'#22c55e':v==='medium'?'#f5b942':v==='bad'?'#ef5350':'#1a3245'}
function nxMindsetRender(){
 const host=document.getElementById('tool');if(!host)return;
 const data=nxMindsetRead(),yr=Number(nxMindsetYear),first=new Date(yr,0,1),firstMon=new Date(first);firstMon.setDate(first.getDate()-(first.getDay()+6)%7);
 const last=new Date(yr,11,31),lastSun=new Date(last);lastSun.setDate(last.getDate()+(7-last.getDay())%7);
 const weekCount=Math.round((lastSun-firstMon)/604800000)+1,monthNames=['Janv','Févr','Mars','Avr','Mai','Juin','Juil','Août','Sept','Oct','Nov','Déc'];
 let monthGroups=[],weeks='';
 for(let wi=0;wi<weekCount;wi++){let wd=new Date(firstMon);wd.setDate(firstMon.getDate()+wi*7+3);monthGroups.push(wd.getFullYear()<yr?0:wd.getFullYear()>yr?11:wd.getMonth())}
 for(let w=0;w<weekCount;w++){
  let d=new Date(firstMon);d.setDate(firstMon.getDate()+w*7);let th=new Date(d);th.setDate(th.getDate()+3);let jan4=new Date(th.getFullYear(),0,4),isoMonday=new Date(jan4);isoMonday.setDate(jan4.getDate()-(jan4.getDay()+6)%7);let wn=1+Math.round((d-isoMonday)/604800000),cells='';
  for(let day=0;day<7;day++){let x=new Date(d);x.setDate(d.getDate()+day);let key=nxMindsetIso(x),inYear=x.getFullYear()===yr,status=data[key]||'';cells+=`<button type="button" class="ms-cell ${key===nxMindsetSelected?'selected':''}" title="${key} — ${nxMindsetStatusName(status)}" aria-label="${key}, ${nxMindsetStatusName(status)}" onclick="nxMindsetSelect('${key}')" style="background:${inYear?nxMindsetColor(status):'transparent'};opacity:${inYear?1:.15}" ${inYear?'':'disabled'}></button>`}
  let monthStart=w===0||monthGroups[w]!==monthGroups[w-1],monthEnd=w===weekCount-1||monthGroups[w]!==monthGroups[w+1];
  weeks+=`<div class="ms-weekrow-grid">${monthStart?`<span class="ms-monthtag" style="grid-row:span ${monthGroups.filter((m,i)=>i>=w&&m===monthGroups[w]).length};writing-mode:vertical-rl;transform:rotate(180deg);display:flex;align-items:center;justify-content:center;background:#19374d;border:1px solid #31516b;border-radius:4px;color:#cfe4f8;font-weight:700">${monthNames[monthGroups[w]]}</span>`:'<span class="ms-monthblank"></span>'}<span class="ms-weeknum">${String(wn).padStart(2,'0')}</span>${cells}</div>`;
 }
 // Merge consecutive month labels in the same way as the original yearly overview.
 const rows=[...Array.from({length:weekCount},(_,i)=>i)];
 let merged='',i=0;while(i<rows.length){let j=i+1;while(j<rows.length&&monthGroups[j]===monthGroups[i])j++;let label=`<span class="ms-monthtag" style="grid-row:span ${j-i};writing-mode:vertical-rl;transform:rotate(180deg);display:flex;align-items:center;justify-content:center;background:#19374d;border:1px solid #31516b;border-radius:4px;color:#cfe4f8;font-weight:700">${monthNames[monthGroups[i]]}</span>`;for(let w=i;w<j;w++){let d=new Date(firstMon);d.setDate(firstMon.getDate()+w*7);let th=new Date(d);th.setDate(th.getDate()+3);let jan4=new Date(th.getFullYear(),0,4),isoMonday=new Date(jan4);isoMonday.setDate(jan4.getDate()-(jan4.getDay()+6)%7);let wn=1+Math.round((d-isoMonday)/604800000),cells='';for(let day=0;day<7;day++){let x=new Date(d);x.setDate(d.getDate()+day);let key=nxMindsetIso(x),inYear=x.getFullYear()===yr,status=data[key]||'';cells+=`<button type="button" class="ms-cell ${key===nxMindsetSelected?'selected':''}" title="${key} — ${nxMindsetStatusName(status)}" aria-label="${key}, ${nxMindsetStatusName(status)}" onclick="nxMindsetSelect('${key}')" style="background:${inYear?nxMindsetColor(status):'transparent'};opacity:${inYear?1:.15}" ${inYear?'':'disabled'}></button>`}merged+=`<div class="ms-weekrow-grid">${w===i?label:'<span class="ms-monthblank"></span>'}<span class="ms-weeknum">${String(wn).padStart(2,'0')}</span>${cells}</div>`}i=j}
 const selectedStatus=data[nxMindsetSelected]||'';
 const yearOptions=Array.from({length:11},(_,i)=>nxMindsetYear-5+i).map(y=>`<option value="${y}" ${y===yr?'selected':''}>${y}</option>`).join('');
 host.innerHTML=`<div class="ms-dash"><div class="ms-top"><div><div class="ms-brand">Mindset</div><div class="ms-muted">Identifie ton niveau de bien-être chaque jour</div></div></div><section class="ms-panel"><div class="ms-title">Journée sélectionnée</div><div class="ms-muted" style="margin-bottom:8px">${nxMindsetSelected.split('-').reverse().join('/')}</div><div class="ms-muted" style="margin-bottom:12px">Statut actuel : <strong>${nxMindsetStatusName(selectedStatus)}</strong></div><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px"><button type="button" onclick="nxMindsetSet('good')" style="border:1px solid #22c55e;background:${selectedStatus==='good'?'#22c55e':'#163b32'};color:#fff;border-radius:12px;padding:13px 5px;font-weight:750">😊 Bien</button><button type="button" onclick="nxMindsetSet('medium')" style="border:1px solid #f5b942;background:${selectedStatus==='medium'?'#f5b942':'#3b3320'};color:#fff;border-radius:12px;padding:13px 5px;font-weight:750">😐 Moyen</button><button type="button" onclick="nxMindsetSet('bad')" style="border:1px solid #ef5350;background:${selectedStatus==='bad'?'#ef5350':'#3b2026'};color:#fff;border-radius:12px;padding:13px 5px;font-weight:750">🙁 Mauvais</button></div></section><section class="ms-panel" style="margin-top:12px"><div class="ms-title">Mon année en un coup d'œil</div><div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;margin-bottom:12px;align-items:end"><label style="display:block;min-width:0;color:#aebfd2">Filtrer par jour<input type="date" value="${nxMindsetSelected}" onchange="nxMindsetSelect(this.value)" class="nx-mindset-day-filter" style="text-align:center;text-align-last:center;display:block;box-sizing:border-box;width:100%;height:42px;min-height:42px;max-height:42px;min-width:0;margin-top:6px;padding:0 12px;border-radius:10px;background:#102b40;color:#e6f2ff;border:1px solid #31516b;color-scheme:dark;-webkit-appearance:none;appearance:none;font-size:16px;line-height:normal;overflow:hidden"></label><label style="display:block;min-width:0;color:#aebfd2">Filtrer par année<select onchange="nxMindsetChangeYear(this.value)" style="display:block;box-sizing:border-box;width:100%;height:42px;min-width:0;margin-top:6px;padding:8px;border-radius:10px;background:#102b40;color:#e6f2ff;border:1px solid #31516b">${yearOptions}</select></label></div><div class="ms-muted" style="margin-bottom:8px">${new Date(yr,11,31).getDate()===31&&new Date(yr,1,29).getMonth()===1?366:365} jours · ${weekCount} lignes de semaines · sélectionne une case puis applique un statut</div><div class="ms-heat"><div class="ms-weekrow-grid ms-heat-header"><span></span><span></span>${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<span>${x}</span>`).join('')}</div>${merged}</div><div class="ms-legend"><span><i class="ms-dot" style="background:#22c55e"></i>Bien</span><span><i class="ms-dot" style="background:#f5b942"></i>Moyen</span><span><i class="ms-dot" style="background:#ef5350"></i>Mauvais</span><span><i class="ms-dot" style="background:#1a3245"></i>Non renseigné</span></div></section></div>`;
}
function nxMindsetSelect(date){nxMindsetSelected=date;nxMindsetYear=Number(date.slice(0,4));nxMindsetRender()}
function nxMindsetChangeYear(year){nxMindsetYear=Number(year);if(nxMindsetSelected.slice(0,4)!==String(nxMindsetYear))nxMindsetSelected=String(nxMindsetYear)+'-01-01';nxMindsetRender()}
function nxMindsetSet(status){const d=nxMindsetRead();d[nxMindsetSelected]=status;nxMindsetSave(d);nxMindsetRender();if(typeof toast==='function')toast('Mindset enregistré')}


/* NEXO 2.8.23 — isolated encrypted password manager. No plaintext persistence. */
const pmDBName='nexo-password-manager-v1';let pmKey=null,pmBusy=false,pmEntries=[],pmVisible=null;
function pmLock(){pmKey=null;pmEntries=[];pmVisible=null;pmBusy=false;}
document.addEventListener('visibilitychange',()=>{if(document.hidden){pmLock();if(current==='password-manager')document.getElementById('tool')?.replaceChildren();}else if(current==='password-manager')pmOpen()});
window.addEventListener('pagehide',pmLock);
function pmDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(pmDBName,1);r.onupgradeneeded=()=>{const db=r.result;db.createObjectStore('meta');db.createObjectStore('entries',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function pmRead(store,id){const db=await pmDb();return new Promise((ok,no)=>{const tx=db.transaction(store,'readonly'),r=tx.objectStore(store)[id===undefined?'getAll':'get'](...(id===undefined?[]:[id]));r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);tx.oncomplete=()=>db.close()})}
async function pmWrite(store,value,id){const db=await pmDb();return new Promise((ok,no)=>{const tx=db.transaction(store,'readwrite');if(id===undefined)tx.objectStore(store).put(value);else tx.objectStore(store).put(value,id);tx.oncomplete=()=>{db.close();ok()};tx.onerror=()=>no(tx.error)})}
async function pmDelete(id){const db=await pmDb();return new Promise((ok,no)=>{const tx=db.transaction('entries','readwrite');tx.objectStore('entries').delete(id);tx.oncomplete=()=>{db.close();ok()};tx.onerror=()=>no(tx.error)})}
const pmRandom=n=>crypto.getRandomValues(new Uint8Array(n));
function pmB64(a){return btoa(String.fromCharCode(...new Uint8Array(a)))}
function pmUnb64(s){return Uint8Array.from(atob(s),x=>x.charCodeAt(0))}
async function pmDerive(pass,salt){const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:pmUnb64(salt),iterations:600000,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function pmWrap(raw,secret){const salt=pmB64(pmRandom(16)),iv=pmRandom(12),key=await pmDerive(secret,salt);return {salt,iv:pmB64(iv),data:pmB64(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,raw))}}
async function pmUnwrap(w,secret){const key=await pmDerive(secret,w.salt);return crypto.subtle.decrypt({name:'AES-GCM',iv:pmUnb64(w.iv)},key,pmUnb64(w.data))}
async function pmEncrypt(value){const iv=pmRandom(12),data=await crypto.subtle.encrypt({name:'AES-GCM',iv},pmKey,new TextEncoder().encode(JSON.stringify(value)));return {iv:pmB64(iv),data:pmB64(data)}}
async function pmDecrypt(x){return JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:pmUnb64(x.iv)},pmKey,pmUnb64(x.data))))}
function pmRecovery(){return Array.from(pmRandom(32),x=>x.toString(16).padStart(2,'0')).join('').match(/.{1,8}/g).join('-')}
function pmPanel(html){const el=document.getElementById('pmScreen');if(el)el.innerHTML=html}
function pmOpen(){content('<div class="stack" id="pmScreen"><p class="muted">Chargement du gestionnaire sécurisé…</p></div>');pmStart()}
async function pmStart(){try{const meta=await pmRead('meta','config');if(current!=='password-manager')return;if(!meta){pmPanel(`<div class="card stack"><h2>🗝️ Créer mon gestionnaire</h2><p class="muted">Identifiants chiffrés sur cet appareil. Coffre indépendant de Mes documents. Mot de passe maître demandé à chaque ouverture.</p><input class="field" type="password" id="pmNew" autocomplete="new-password" placeholder="Mot de passe maître (12 caractères minimum)"><input class="field" type="password" id="pmConfirm" autocomplete="new-password" placeholder="Confirmer le mot de passe"><button class="btn primary" onclick="pmCreate()">Créer mon gestionnaire</button></div>`);return}if(!pmKey){pmPanel(`<div class="card stack"><h2>🔒 Mes mots de passe</h2><input class="field" type="password" id="pmPass" autocomplete="off" placeholder="Mot de passe maître"><button class="btn primary" onclick="pmUnlock(false)">Déverrouiller</button><button class="btn" onclick="pmRecoveryForm()">Utiliser ma clé de récupération</button><button class="btn" onclick="pmImportPick()">Restaurer une sauvegarde chiffrée</button></div>`);return}await pmList()}catch(e){console.error(e);pmPanel('<div class="card">Stockage sécurisé indisponible. Vérifie que NEXO est ouvert en HTTPS.</div>')}}
async function pmCreate(){if(pmBusy)return;const a=$('#pmNew').value,b=$('#pmConfirm').value;if(a.length<12||a!==b)return toast('12 caractères minimum et confirmation identique');pmBusy=true;try{const raw=pmRandom(32),recovery=pmRecovery(),meta={format:'nexo-password-manager',version:1,pass:await pmWrap(raw,a),recovery:await pmWrap(raw,recovery)};await pmWrite('meta',meta,'config');pmKey=await crypto.subtle.importKey('raw',raw,'AES-GCM',false,['encrypt','decrypt']);pmPanel(`<div class="card stack"><h2>🔑 Clé de récupération</h2><p>Conserve cette clé dans un endroit sûr, hors de NEXO. Elle ne sera plus affichée.</p><textarea class="field" id="pmRecoveryShown" readonly rows="3">${recovery}</textarea><button class="btn" onclick="pmCopy($('#pmRecoveryShown').value)">Copier la clé</button><label><input type="checkbox" id="pmAck"> J’ai conservé ma clé de récupération</label><button class="btn primary" onclick="if(!$('#pmAck').checked)return toast('Conserve ta clé avant de continuer');pmList()">Continuer</button></div>`)}catch(e){console.error(e);toast('Création impossible')}finally{pmBusy=false}}
async function pmUnlock(recover){if(pmBusy)return;const pass=$('#pmPass')?.value||$('#pmRecoveryInput')?.value||'';pmBusy=true;try{const meta=await pmRead('meta','config'),raw=await pmUnwrap(recover?meta.recovery:meta.pass,pass);pmKey=await crypto.subtle.importKey('raw',raw,'AES-GCM',false,['encrypt','decrypt']);await pmList()}catch(e){toast('Mot de passe ou clé incorrecte')}finally{pmBusy=false}}
function pmRecoveryForm(){pmPanel(`<div class="card stack"><h2>Clé de récupération</h2><input class="field" id="pmRecoveryInput" autocomplete="off" placeholder="Clé de récupération"><button class="btn primary" onclick="pmUnlock(true)">Déverrouiller</button><button class="btn" onclick="pmStart()">Retour</button></div>`)}
async function pmList(){if(!pmKey)return pmStart();try{pmEntries=await Promise.all((await pmRead('entries')).map(async x=>({...await pmDecrypt(x),id:x.id})));pmRender()}catch(e){console.error(e);toast('Lecture impossible')}}
function pmRender(){const query=($('#pmSearch')?.value||'').toLocaleLowerCase('fr');const filtered=pmEntries.filter(x=>[x.name,x.user,x.category,x.url].some(v=>String(v||'').toLocaleLowerCase('fr').includes(query))).sort((a,b)=>Number(!!b.favorite)-Number(!!a.favorite)||a.name.localeCompare(b.name,'fr'));pmPanel(`<div class="card stack"><h2>🗝️ Mes mots de passe</h2><p class="muted">${pmEntries.length} identifiant(s) · Stockage local chiffré</p><input class="field" id="pmSearch" value="${esc(query)}" placeholder="Rechercher un site, un identifiant…" oninput="pmFilter()"><div id="pmResults"></div><button class="btn primary" onclick="pmEdit()">+ Ajouter un identifiant</button><button class="btn" onclick="pmExport()">Exporter une sauvegarde chiffrée</button><button class="btn" onclick="pmImportPick()">Importer une sauvegarde chiffrée</button><button class="btn" onclick="pmLock();pmStart()">🔒 Verrouiller</button><p class="muted">La sauvegarde générale NEXO n’inclut pas ce gestionnaire : utilise son export chiffré séparé.</p></div>`);pmFilter()}
function pmFilter(){const el=$('#pmResults');if(!el)return;const q=($('#pmSearch')?.value||'').toLocaleLowerCase('fr');const a=pmEntries.filter(x=>[x.name,x.user,x.category,x.url].some(v=>String(v||'').toLocaleLowerCase('fr').includes(q))).sort((a,b)=>Number(!!b.favorite)-Number(!!a.favorite)||a.name.localeCompare(b.name,'fr'));el.innerHTML=a.map(x=>`<button class="btn" style="width:100%;text-align:left;margin:5px 0" onclick="pmDetail('${x.id}')">${x.favorite?'⭐ ':''}${esc(x.name||'Sans titre')} <small>— ${esc(x.user||'')}</small></button>`).join('')||'<p class="muted">Aucun identifiant trouvé.</p>'}
function pmDetail(id){const x=pmEntries.find(y=>y.id===id);if(!x)return;pmVisible=null;pmPanel(`<div class="card stack"><h2>${esc(x.name)}</h2><p class="muted">${esc(x.category||'Sans catégorie')}</p><label>Identifiant<input class="field" readonly value="${esc(x.user||'')}"></label><button class="btn" onclick="pmCopy(pmEntries.find(x=>x.id==='${id}').user)">Copier l’identifiant</button><label>Mot de passe<input class="field" id="pmSecret" type="password" readonly value="${esc(x.password||'')}"></label><button class="btn" onclick="$('#pmSecret').type=$('#pmSecret').type==='password'?'text':'password'">Afficher / masquer</button><button class="btn" onclick="pmCopy(pmEntries.find(x=>x.id==='${id}').password)">Copier le mot de passe</button>${x.url?`<p>Site : ${esc(x.url)}</p>`:''}${x.notes?`<p>Notes : ${esc(x.notes)}</p>`:''}<button class="btn primary" onclick="pmEdit('${id}')">Modifier</button><button class="btn" onclick="pmRemove('${id}')">Supprimer</button><button class="btn" onclick="pmRender()">← Retour</button></div>`)}
function pmEdit(id){const x=pmEntries.find(y=>y.id===id)||{};pmPanel(`<div class="card stack"><h2>${id?'Modifier':'Nouvel'} identifiant</h2><label>Nom du service<input class="field" id="pmName" maxlength="120" value="${esc(x.name||'')}" placeholder="Ex. Google"></label><label>Identifiant ou e-mail<input class="field" id="pmUser" maxlength="250" value="${esc(x.user||'')}" autocomplete="off"></label><label>Mot de passe<input class="field" type="password" id="pmPassword" value="${esc(x.password||'')}" autocomplete="new-password"></label><button class="btn" onclick="pmGenerate()">Générer un mot de passe</button><label>Site web<input class="field" id="pmUrl" value="${esc(x.url||'')}" placeholder="https://..."></label><label>Catégorie<input class="field" id="pmCategory" maxlength="80" value="${esc(x.category||'')}"></label><label>Notes<textarea class="field" id="pmNotes" rows="3">${esc(x.notes||'')}</textarea></label><label><input type="checkbox" id="pmFavorite" ${x.favorite?'checked':''}> Favori</label><button class="btn primary" onclick="pmSave('${id||''}')">Enregistrer</button><button class="btn" onclick="pmRender()">Annuler</button></div>`)}
function pmGenerate(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*-_+=?',a=new Uint32Array(24);crypto.getRandomValues(a);$('#pmPassword').value=Array.from(a,n=>chars[n%chars.length]).join('');$('#pmPassword').type='text'}
async function pmSave(id){if(pmBusy||!pmKey)return;const x={name:$('#pmName').value.trim(),user:$('#pmUser').value.trim(),password:$('#pmPassword').value,url:$('#pmUrl').value.trim(),category:$('#pmCategory').value.trim(),notes:$('#pmNotes').value,favorite:$('#pmFavorite').checked};if(!x.name||!x.password)return toast('Nom et mot de passe obligatoires');pmBusy=true;try{const key=id||crypto.randomUUID(),enc=await pmEncrypt(x);await pmWrite('entries',{id:key,...enc});await pmList();toast('Identifiant enregistré')}catch(e){console.error(e);toast('Enregistrement impossible')}finally{pmBusy=false}}
async function pmRemove(id){if(!confirm('Supprimer définitivement cet identifiant ?'))return;await pmDelete(id);await pmList();toast('Identifiant supprimé')}
async function pmCopy(value){try{await navigator.clipboard.writeText(value||'');toast('Copié — pense à vider le presse-papiers')}catch(e){toast('Copie impossible')}}
async function pmExport(){try{const meta=await pmRead('meta','config'),entries=await pmRead('entries'),payload={format:'nexo-password-manager-backup',version:1,createdAt:new Date().toISOString(),meta,entries};const blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='NEXO_passwords_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);toast('Sauvegarde chiffrée exportée')}catch(e){console.error(e);toast('Export impossible')}}
function pmImportPick(){const inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.onchange=()=>pmImport(inp.files?.[0]);inp.click()}
async function pmImport(file){if(!file)return;try{if(file.size>30*1024*1024)throw Error('Taille excessive');const data=JSON.parse(await file.text());if(data.format!=='nexo-password-manager-backup'||data.version!==1||!data.meta?.pass||!data.meta?.recovery||!Array.isArray(data.entries)||data.entries.some(x=>!x.id||!x.iv||!x.data))throw Error('Format invalide');if(!confirm('La restauration remplacera tous les identifiants et le mot de passe maître de ce gestionnaire. Continuer ?'))return;const db=await pmDb();await new Promise((ok,no)=>{const tx=db.transaction(['meta','entries'],'readwrite');tx.objectStore('meta').put(data.meta,'config');tx.objectStore('entries').clear();for(const item of data.entries)tx.objectStore('entries').put(item);tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});db.close();pmLock();pmStart();toast('Sauvegarde restaurée : utilise son ancien mot de passe maître')}catch(e){console.error(e);toast('Fichier invalide ou restauration impossible')}}


/* NEXO Scanner PDF v2.8.34 : document processing on-device, no remote service */
const nxPdf={pages:[],selected:0,signature:null,signatureCanvas:null,editMode:false,signPlacement:null};
function nxPdfOpen(){content(`<div class="card stack nxpdf-section"><h2>📄 Scanner PDF</h2><div class="nxpdf-toolbar"><button class="btn primary" onclick="document.getElementById('nxpdf-camera').click()">Photographier</button><button class="btn" onclick="document.getElementById('nxpdf-files').click()">Importer des photos</button></div><input id="nxpdf-camera" type="file" accept="image/*" capture="environment" style="display:none" onchange="nxPdfAdd(this)"><input id="nxpdf-files" type="file" accept="image/*" multiple style="display:none" onchange="nxPdfAdd(this)"></div><div class="card stack nxpdf-section" style="margin-top:12px"><h3>Pages du document</h3><div id="nxpdf-list" class="nxpdf-pages"></div><p id="nxpdf-empty" class="muted">Aucune page. Ajoute une photo pour commencer.</p></div><div id="nxpdf-workspace" style="display:none" class="card stack nxpdf-section"><h3>Modifier une page</h3><div id="nxpdf-preview" class="nxpdf-editor"><canvas id="nxpdf-canvas"></canvas></div><p class="nxpdf-editor-hint">En mode signature, déplace la signature avec un doigt sur la page.</p><div class="two"><label>Filtre<select id="nxpdf-filter" class="field" onchange="nxPdfUpdate()"><option value="color">Couleur</option><option value="gray">Niveaux de gris</option><option value="bw">Noir et blanc</option></select></label><label>Rotation<select id="nxpdf-rotate" class="field" onchange="nxPdfUpdate()"><option value="0">0°</option><option value="90">90°</option><option value="180">180°</option><option value="270">270°</option></select></label></div><label>Recadrage (marges identiques) <input id="nxpdf-crop" type="range" min="0" max="25" value="0" oninput="nxPdfUpdate()"></label><div class="nxpdf-toolbar"><button class="btn" onclick="nxPdfUseSignature()">✍️ Placer la signature</button><button class="btn" onclick="nxPdfRemoveSignature()">Retirer la signature</button></div><label>Taille de signature <input id="nxpdf-signsize" type="range" min="15" max="75" value="38" oninput="nxPdfResizeSignature()"></label></div><div class="card stack nxpdf-section" style="margin-top:12px"><h3>Signature manuscrite</h3><p class="muted">Signe au doigt dans le cadre, puis choisis « Placer la signature » sur la page souhaitée.</p><canvas class="nxpdf-signature" id="nxpdf-pad"></canvas><div class="nxpdf-toolbar"><button class="btn" onclick="nxPdfClearSignature()">Effacer</button><button class="btn primary" onclick="nxPdfSaveSignature()">Conserver cette signature</button></div><p class="nxpdf-note">Signature électronique simple, non certifiée.</p></div><div class="card stack nxpdf-section" style="margin-top:12px"><h3>Exporter</h3><label class="nxpdf-filename-label">Nom du fichier<input id="nxpdf-name" class="field" value="Document" maxlength="90" placeholder="Nom du PDF"></label><div class="nxpdf-toolbar"><button class="btn primary" onclick="nxPdfExport(false)">⬇ Exporter PDF</button><button class="btn" onclick="nxPdfExport(true)">↗ Partager / envoyer</button></div></div>`);nxPdfRender();nxPdfSetupPad()}
async function nxPdfAdd(el){const files=[...el.files];el.value='';if(!files.length)return;for(const file of files){try{const img=await createImageBitmap(file);const max=1800,ratio=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*ratio);c.height=Math.round(img.height*ratio);c.getContext('2d').drawImage(img,0,0,c.width,c.height);img.close();nxPdf.pages.push({src:c.toDataURL('image/jpeg',.87),filter:'color',rotate:0,crop:0,sign:null});}catch(e){console.error(e);toast('Photo illisible : '+file.name)}}nxPdf.selected=nxPdf.pages.length-1;nxPdfRender()}
function nxPdfRender(){const list=document.getElementById('nxpdf-list');if(!list)return;list.innerHTML=nxPdf.pages.map((p,i)=>`<div class="nxpdf-page"><img src="${p.src}" alt="Page ${i+1}"><div>Page ${i+1}</div><div class="nxpdf-controls"><button class="btn" onclick="nxPdfSelect(${i})">Modifier</button><button class="btn" onclick="nxPdfMove(${i},-1)" ${i===0?'disabled':''}>↑</button><button class="btn" onclick="nxPdfMove(${i},1)" ${i===nxPdf.pages.length-1?'disabled':''}>↓</button><button class="btn" onclick="nxPdfDelete(${i})">✕</button></div></div>`).join('');document.getElementById('nxpdf-empty').style.display=nxPdf.pages.length?'none':'';document.getElementById('nxpdf-workspace').style.display=nxPdf.pages.length?'':'none';if(nxPdf.pages.length){nxPdf.selected=Math.min(nxPdf.selected,nxPdf.pages.length-1);const p=nxPdf.pages[nxPdf.selected];document.getElementById('nxpdf-filter').value=p.filter;document.getElementById('nxpdf-rotate').value=p.rotate;document.getElementById('nxpdf-crop').value=p.crop;document.getElementById('nxpdf-signsize').value=p.sign?.size||38;nxPdfPreview()}}
function nxPdfSelect(i){nxPdf.selected=i;nxPdfRender();document.getElementById('nxpdf-workspace').scrollIntoView({behavior:'smooth',block:'start'})}
function nxPdfMove(i,dir){const j=i+dir;if(j<0||j>=nxPdf.pages.length)return;[nxPdf.pages[i],nxPdf.pages[j]]=[nxPdf.pages[j],nxPdf.pages[i]];nxPdf.selected=j;nxPdfRender()}
function nxPdfDelete(i){nxPdf.pages.splice(i,1);nxPdf.selected=Math.max(0,Math.min(nxPdf.selected,nxPdf.pages.length-1));nxPdfRender()}
function nxPdfUpdate(){const p=nxPdf.pages[nxPdf.selected];if(!p)return;p.filter=document.getElementById('nxpdf-filter').value;p.rotate=Number(document.getElementById('nxpdf-rotate').value);p.crop=Number(document.getElementById('nxpdf-crop').value);nxPdfPreview()}
function nxPdfImage(src){return new Promise((res,rej)=>{const img=new Image();img.onload=()=>res(img);img.onerror=rej;img.src=src})}
async function nxPdfPaint(p,limit=1400){const img=await nxPdfImage(p.src);const cut=p.crop/100,w=img.naturalWidth,h=img.naturalHeight;const sw=w*(1-2*cut),sh=h*(1-2*cut);const rot=p.rotate%180!==0;const ow=rot?sh:sw,oh=rot?sw:sh;const factor=Math.min(1,limit/Math.max(ow,oh));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(ow*factor));c.height=Math.max(1,Math.round(oh*factor));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.save();ctx.translate(c.width/2,c.height/2);ctx.rotate(p.rotate*Math.PI/180);ctx.filter=p.filter==='gray'?'grayscale(1)':p.filter==='bw'?'grayscale(1) contrast(2.4)':'none';ctx.drawImage(img,w*cut,h*cut,sw,sh,-sw*factor/2,-sh*factor/2,sw*factor,sh*factor);ctx.restore();if(p.sign?.src){const sig=await nxPdfImage(p.sign.src);const size=p.sign.size/100*c.width;const hh=size*sig.naturalHeight/sig.naturalWidth;ctx.drawImage(sig,p.sign.x*c.width-size/2,p.sign.y*c.height-hh/2,size,hh)}return c}
let nxPdfPreviewSeq=0;
async function nxPdfPreview(){const p=nxPdf.pages[nxPdf.selected],canvas=document.getElementById('nxpdf-canvas');if(!p||!canvas)return;const seq=++nxPdfPreviewSeq;try{const result=await nxPdfPaint(p,1000);if(seq!==nxPdfPreviewSeq)return;canvas.width=result.width;canvas.height=result.height;canvas.getContext('2d').drawImage(result,0,0)}catch(e){console.error(e)}}
function nxPdfSetupPad(){const pad=document.getElementById('nxpdf-pad');if(!pad)return;const rect=pad.getBoundingClientRect();pad.width=Math.max(300,Math.round(rect.width*devicePixelRatio));pad.height=Math.round(145*devicePixelRatio);const ctx=pad.getContext('2d');ctx.scale(devicePixelRatio,devicePixelRatio);ctx.strokeStyle='#172b49';ctx.lineWidth=2.5;ctx.lineCap='round';ctx.lineJoin='round';let drawing=false;const pos=e=>{const r=pad.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]};pad.onpointerdown=e=>{e.preventDefault();drawing=true;pad.setPointerCapture(e.pointerId);const [x,y]=pos(e);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+.1,y+.1);ctx.stroke()};pad.onpointermove=e=>{if(!drawing)return;e.preventDefault();const [x,y]=pos(e);ctx.lineTo(x,y);ctx.stroke()};pad.onpointerup=pad.onpointercancel=()=>drawing=false;const preview=document.getElementById('nxpdf-canvas');preview.onpointerdown=e=>{const p=nxPdf.pages[nxPdf.selected];if(!p?.sign)return;e.preventDefault();preview.setPointerCapture(e.pointerId);nxPdfPlaceAt(e)};preview.onpointermove=e=>{if(e.buttons&&nxPdf.pages[nxPdf.selected]?.sign){e.preventDefault();nxPdfPlaceAt(e)}}}
function nxPdfPlaceAt(e){const c=document.getElementById('nxpdf-canvas'),r=c.getBoundingClientRect(),p=nxPdf.pages[nxPdf.selected];p.sign.x=Math.max(.05,Math.min(.95,(e.clientX-r.left)/r.width));p.sign.y=Math.max(.05,Math.min(.95,(e.clientY-r.top)/r.height));nxPdfPreview()}
function nxPdfClearSignature(){const c=document.getElementById('nxpdf-pad');c?.getContext('2d').clearRect(0,0,c.width,c.height);nxPdf.signature=null}
function nxPdfSaveSignature(){const pad=document.getElementById('nxpdf-pad');if(!pad)return;const ctx=pad.getContext('2d'),d=ctx.getImageData(0,0,pad.width,pad.height).data;let xmin=pad.width,ymin=pad.height,xmax=0,ymax=0;for(let y=0;y<pad.height;y+=2)for(let x=0;x<pad.width;x+=2){if(d[(y*pad.width+x)*4+3]>20){xmin=Math.min(xmin,x);xmax=Math.max(xmax,x);ymin=Math.min(ymin,y);ymax=Math.max(ymax,y)}}if(xmax<=xmin||ymax<=ymin){toast('Dessine ta signature avant de continuer');return}const c=document.createElement('canvas');c.width=xmax-xmin+12;c.height=ymax-ymin+12;c.getContext('2d').drawImage(pad,xmin-6,ymin-6,c.width,c.height,0,0,c.width,c.height);nxPdf.signature=c.toDataURL('image/png');toast('Signature prête à placer')}
function nxPdfUseSignature(){const p=nxPdf.pages[nxPdf.selected];if(!p)return;if(!nxPdf.signature){toast('Dessine et conserve ta signature d’abord');return}p.sign={src:nxPdf.signature,x:.5,y:.83,size:Number(document.getElementById('nxpdf-signsize').value)};nxPdfPreview();toast('Déplace la signature au doigt sur la page')}
function nxPdfRemoveSignature(){const p=nxPdf.pages[nxPdf.selected];if(p){p.sign=null;nxPdfPreview()}}
function nxPdfResizeSignature(){const p=nxPdf.pages[nxPdf.selected];if(p?.sign){p.sign.size=Number(document.getElementById('nxpdf-signsize').value);nxPdfPreview()}}
/* Small local JPEG/A4 PDF writer; every page embeds a rendered image. */
function nxPdfMake(pages){const enc=new TextEncoder(),parts=[],offsets=[0];let bytes=0;const push=a=>{parts.push(a);bytes+=a.length};const ascii=s=>push(enc.encode(s));ascii('%PDF-1.4\n');const obj=(n,body)=>{offsets[n]=bytes;ascii(n+' 0 obj\n'+body+'\nendobj\n')};const total=2+pages.length*3;obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Kids [${pages.map((_,i)=>3+i*3+' 0 R').join(' ')}] /Count ${pages.length} >>`);pages.forEach((p,i)=>{const n=3+i*3,image=n+1,stream=n+2;const W=595.28,H=841.89,scale=Math.min(W/p.w,H/p.h),dw=p.w*scale,dh=p.h*scale,x=(W-dw)/2,y=(H-dh)/2;obj(n,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /XObject << /Im${i} ${image} 0 R >> >> /Contents ${stream} 0 R >>`);offsets[image]=bytes;ascii(`${image} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${p.w} /Height ${p.h} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${p.jpg.length} >>\nstream\n`);push(p.jpg);ascii('\nendstream\nendobj\n');const cmd=`q\n${dw.toFixed(3)} 0 0 ${dh.toFixed(3)} ${x.toFixed(3)} ${y.toFixed(3)} cm\n/Im${i} Do\nQ\n`;obj(stream,`<< /Length ${enc.encode(cmd).length} >>\nstream\n${cmd}endstream`)});const xref=bytes;ascii(`xref\n0 ${total+1}\n0000000000 65535 f \n`);for(let i=1;i<=total;i++)ascii(String(offsets[i]).padStart(10,'0')+' 00000 n \n');ascii(`trailer\n<< /Size ${total+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
async function nxPdfExport(share){if(!nxPdf.pages.length){toast('Ajoute au moins une page');return}const btns=[...document.querySelectorAll('#tool button')].filter(x=>x.textContent.includes('Exporter PDF')||x.textContent.includes('Partager / envoyer'));btns.forEach(b=>b.disabled=true);try{const pages=[];for(const p of nxPdf.pages){const c=await nxPdfPaint(p,1700);const b64=c.toDataURL('image/jpeg',.85).split(',')[1];const bin=atob(b64),arr=new Uint8Array(bin.length);for(let j=0;j<bin.length;j++)arr[j]=bin.charCodeAt(j);pages.push({w:c.width,h:c.height,jpg:arr})}const blob=nxPdfMake(pages);const raw=(document.getElementById('nxpdf-name').value||'Document').trim().replace(/[\\/:*?"<>|]/g,'_');const name=(raw||'Document')+'.pdf';const file=new File([blob],name,{type:'application/pdf'});if(share&&navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:name})}else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);if(share)toast('Partage indisponible : PDF téléchargé')} }catch(e){if(e.name!=='AbortError'){console.error(e);toast('Erreur de création du PDF')}}finally{btns.forEach(b=>b.disabled=false)}}
;
/* NEXO 2.8.44: read-only, on-demand universal search. No data migration. */
(function(){
const sources=[
 ['Modules','',null],['Mon garage','garageVehicles','garage'],['Voyages','travel_v10','travel'],
 ['Notes','notes','notes'],['To-do list','tasks','todo'],['Liste de courses','shopping','shopping'],
 ['Dépenses','expenses','expenses'],['Entrées','incomeEntries','expenses'],
 ['Recettes','nexoRecipes','recipes'],['Sport','sportSessions','sport'],
 ['Parking','nexoParking','parking']
];
let results=[],activeQuery='';
const normalize=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr').trim();
const safeText=v=>{if(typeof v==='string'||typeof v==='number')return String(v);return ''};
const escapeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function flatten(value,depth=0){
 if(depth>4||value==null)return '';
 if(typeof value==='string'||typeof value==='number')return String(value);
 if(Array.isArray(value))return value.slice(0,150).map(x=>flatten(x,depth+1)).join(' ');
 if(typeof value==='object')return Object.entries(value).filter(([k])=>!/(?:base64|image|photo|blob|binary|contentdata|signature|password|secret|token)/i.test(k)).slice(0,45).map(([,v])=>flatten(v,depth+1)).join(' ');
 return '';
}
function label(item,group){
 if(typeof item==='string')return item;
 if(!item||typeof item!=='object')return String(item??'');
 const props=['title','name','label','model','destination','desc','description','text','category','type'];
 const value=props.map(k=>safeText(item[k])).find(Boolean);
 return value||group+' · '+safeText(item.date||item.id||'Élément');
}
function read(key){
 try{const v=JSON.parse(localStorage.getItem('tb_'+key)||'[]');return Array.isArray(v)?v:(v&&typeof v==='object'?[v]:[])}catch{return []}
}
function allResults(q){
 const needle=normalize(q);if(!needle)return [];
 const vehicles=read('garageVehicles');
 const matchedVehicleIds=new Set(vehicles.filter(v=>normalize(flatten(v)).includes(needle)).map(v=>String(v.id)));
 const out=[];
 for(const [group,key,target] of sources){
  if(!key)continue;
  const items=key==='travel_v10'&&typeof travelStore==='function'?travelStore():
    key==='nexoRecipes'&&typeof recipeList==='function'?recipeList():read(key);
  if(!Array.isArray(items))continue;
  items.forEach((item,index)=>{
   const searchable=group==='Voyages'
     ? [item?.title,item?.name,item?.destination,item?.country,item?.city,item?.location,item?.subtitle].map(safeText).join(' ')
     : group==='Recettes'
     ? [item?.title,item?.name,item?.category,...(Array.isArray(item?.ingredients)?item.ingredients.map(x=>typeof x==='string'?x:safeText(x?.name)):[])].join(' ')
     : flatten(item);
   const linked=group.startsWith('Entretien')&&matchedVehicleIds.size&&['vehicleId','vehicle_id','vehicle','vehId'].some(k=>matchedVehicleIds.has(String(item?.[k])));
   if(!normalize(searchable).includes(needle)&&!linked)return;
   out.push({group,title:label(item,group),detail:safeText(item?.date||item?.category||item?.type||''),target,id:item?.id,index});
  });
 }
 if(typeof defs!=='undefined')defs.forEach(d=>{
  if(normalize(d[2]+' '+(d[3]||'')).includes(needle))out.push({group:'Modules',title:d[2],detail:d[3]||'',target:d[0]});
 });
 // PDF documents: titles only, never extract document contents.
 for(let i=0;i<localStorage.length;i++){
  const key=localStorage.key(i);
  if(!key||!/^tb_/.test(key)||!/(?:pdf|document)/i.test(key)||/(?:password|vault|coffre|secret)/i.test(key))continue;
  let value;try{value=JSON.parse(localStorage.getItem(key))}catch{continue}
  if(!Array.isArray(value))continue;
  value.forEach((item,index)=>{
   const title=safeText(item?.title||item?.name||item?.filename);
   if(title&&normalize(title).includes(needle))out.push({group:'Documents PDF',title,detail:'Titre du document',target:'scanner-pdf',index});
  });
 }
 return out.slice(0,250);
}
window.nxSearchOpen=function(){
 if(typeof cleanup==='function')cleanup();
 current='nx-search';nav('');setHead('Recherche','');window.scrollTo(0,0);
 app.innerHTML='<div class="nx-search-page"><div class="nx-search-input-row"><span style="color:#3299ff" aria-hidden="true"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/></svg></span><input id="nx-search-query" type="search" autocomplete="off" placeholder="Rechercher dans NEXO..." aria-label="Rechercher dans NEXO"><button type="button" class="btn" onclick="gen2Home()" aria-label="Fermer la recherche">✕</button></div><div id="nx-search-results" aria-live="polite"><div class="nx-search-empty">Rechercher un module, un voyage, un véhicule, une note, un document…</div></div></div>';
 const input=document.getElementById('nx-search-query');input.addEventListener('input',()=>window.nxSearchRender(input.value));input.focus();
};
window.nxSearchRender=function(query){
 activeQuery=query;results=allResults(query);
 const target=document.getElementById('nx-search-results');if(!target)return;
 if(!query.trim()){target.innerHTML='<div class="nx-search-empty">Saisis un mot pour rechercher dans NEXO.</div>';return}
 if(!results.length){target.innerHTML='<div class="nx-search-empty">Aucun résultat trouvé.</div>';return}
 const groups=[...new Set(results.map(r=>r.group))];
 target.innerHTML=groups.map(group=>'<section class="nx-search-group"><h3>'+escapeText(group)+' ('+results.filter(r=>r.group===group).length+')</h3>'+results.map((r,i)=>r.group===group?'<button class="nx-search-hit" type="button" onclick="nxSearchGo('+i+')"><span><strong>'+escapeText(r.title)+'</strong><small>'+escapeText(r.detail)+'</small></span><span aria-hidden="true">›</span></button>':'').join('')+'</section>').join('');
};
window.nxSearchGo=function(i){
 const r=results[i];if(!r)return;
 if(r.group==='Voyages'&&typeof travelOpen==='function'){
   const tripId=r.id;
   openTool('travel');
   // travel() launches an asynchronous list render. Wait for it before opening
   // the selected trip, otherwise the list can overwrite the detail screen.
   Promise.resolve(typeof nxTravelStartup!=='undefined'?nxTravelStartup:null)
     .then(()=>typeof travelList==='function'?travelList():null)
     .then(()=>{
       const trips=typeof travelStore==='function'?travelStore():[];
       const trip=trips.find(x=>String(x.id)===String(tripId))||trips[r.index];
       if(trip)travelOpen(trip.id);
     }).catch(err=>console.error('Ouverture directe voyage',err));
   return;
 }
 if(r.group==='Recettes'){
   // Resolve the actual recipe before changing screens; use its original ID.
   // Never use the search result index as an ID.
   const recipesNow=typeof recipeList==='function'?recipeList():[];
   const recipe=recipesNow.find(x=>String(x.id)===String(r.id))||
     recipesNow.find(x=>x.title===r.title);
   if(!recipe){console.warn('Recette introuvable dans la recherche',r);return}
   const recipeId=recipe.id;
   openTool('recipes');
   // Open after module initialization and its render have completed.
   requestAnimationFrame(()=>{
     try{recipeView(recipeId)}
     catch(e){console.error('Ouverture directe de recette',e)}
   });
   return;
 }
 if(r.group==='Notes'){
   openTool('notes');
   const notesNow=typeof get==='function'?get('notes',[]):[];
   const note=notesNow.find(x=>String(x.id)===String(r.id))||notesNow[r.index];
   if(note){
     const title=typeof esc==='function'?esc(note.title||'Sans titre'):String(note.title||'Sans titre');
     const body=typeof esc==='function'?esc(note.body||''):String(note.body||'');
     content('<div class="card stack"><button class="btn" onclick="notes()">← Mes notes</button><h2>'+title+'</h2><div style="white-space:pre-wrap;overflow-wrap:anywhere">'+body+'</div><button class="btn" id="nx-note-edit">Modifier cette note</button></div>');
     const edit=document.getElementById('nx-note-edit');
     if(edit)edit.addEventListener('click',()=>{notes();editNote(note.id)});
     return;
   }
 }
 if(r.group==='Mon garage'&&r.id!=null&&typeof garageOpen==='function'){openTool('garage');garageOpen(r.id);return}
 if(typeof openTool==='function')openTool(r.target||'');
};
})();
;
/* Optional edge-swipe back. Reuse the screen's own Back button so that
   each module keeps its existing navigation and cleanup semantics. */
(function(){
 let start=null;
 const edge=32, minDistance=85, maxVertical=65;
 const excluded='input,textarea,select,[contenteditable="true"],.nx-recipe-portions-row';
 function findBack(){
   // Prefer the back control inside the active module screen.
   // The global « Modules » button must only be used if no local back exists.
   const active=document.querySelector('#tool');
   const roots=[active,document.querySelector('#app')].filter(Boolean);
   const candidates=roots.flatMap(root=>[...root.querySelectorAll('button,a,[role="button"]')]);
   return candidates.find(el=>{
     if(el.disabled||el.getAttribute('aria-disabled')==='true')return false;
     if(!el.getClientRects().length)return false;
     const text=(el.textContent||'').trim();
     return /^(?:←|‹|❮|⬅)\s*(?:retour|modules|accueil|mes |toutes |liste |catégories|voyages|recettes|précédent)/i.test(text)
       || /^(?:retour|back)$/i.test(el.getAttribute('aria-label')||'');
   });
 }
 document.addEventListener('touchstart',e=>{
   start=null;
   if(e.touches.length!==1)return;
   const t=e.touches[0];
   if(t.clientX>edge || t.clientY<15)return;
   if(e.target.closest(excluded))return;
   if(!findBack())return;
   start={x:t.clientX,y:t.clientY,time:Date.now()};
 },{passive:true});
 document.addEventListener('touchend',e=>{
   if(!start||e.changedTouches.length!==1){start=null;return}
   const a=start;start=null;
   const t=e.changedTouches[0],dx=t.clientX-a.x,dy=t.clientY-a.y;
   if(dx<minDistance||Math.abs(dy)>maxVertical||Math.abs(dx)<Math.abs(dy)*1.5||Date.now()-a.time>1300)return;
   const back=findBack();if(back)back.click();
 },{passive:true});
 document.addEventListener('touchcancel',()=>{start=null},{passive:true});
})();
;
