function nxProfileImg(){return get('nxProfileImage','')}
function nxRenderProfileThumb(){document.querySelectorAll('#nx-profile-thumb').forEach(el=>{const img=nxProfileImg();el.innerHTML=img?`<img src="${img}" alt="Photo de profil">`:'👤'})}
function nxProfilePicture(input){const file=input.files?.[0];if(!file)return;if(file.size>8e6){toast('Photo trop volumineuse');return}const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{const cv=document.createElement('canvas');let side=Math.min(img.width,img.height),scale=Math.min(1,320/side);cv.width=cv.height=Math.round(side*scale);cv.getContext('2d').drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,cv.width,cv.height);try{put('nxProfileImage',cv.toDataURL('image/jpeg',.72));nxRenderProfileThumb();toast('Photo enregistrée')}catch(e){toast('Espace insuffisant pour cette photo')}URL.revokeObjectURL(url)};img.onerror=()=>{URL.revokeObjectURL(url);toast('Image non reconnue')};img.src=url}
function nxRemoveProfilePicture(){put('nxProfileImage','');nxRenderProfileThumb();toast('Photo supprimée')}
function nxSaveProfile(){put('firstName',document.getElementById('nx-profile-name').value.trim());put('nxWelcomeText',document.getElementById('nx-welcome-text').value.trim());put('nxWelcomeEnabled',document.getElementById('nx-welcome-on').checked);toast('Profil enregistré')}
function nxSaveShortcut(){const v=document.getElementById('navChoice1')?.value;if(!v)return;put('bottomNav',[v,navChoices()[1]]);renderBottomNav();toast('Raccourci enregistré')}
function nxModal(inner){nxCloseModal();const el=document.createElement('div');el.className='nx-setting-modal-backdrop';el.id='nx-setting-modal';el.innerHTML=`<section class="nx-setting-modal" role="dialog" aria-modal="true" aria-label="Personnalisation">${inner}</section>`;document.body.appendChild(el);el.addEventListener('click',e=>{if(e.target===el)nxCloseModal()});nxSettingsModal=el}
function nxCloseModal(){document.getElementById('nx-setting-modal')?.remove();nxSettingsModal=null}
function nxEmojiPicker(current){return `<div class="nx-setting-emoji-grid">${NX_SETTING_ICONS.map((ic,i)=>`<button type="button" class="nx-setting-emoji ${ic===current?'selected':''}" data-nx-ic="${i}" onclick="nxSelectSettingsEmoji(this)">${ic}</button>`).join('')}</div>`}
function nxSelectSettingsEmoji(el){el.parentElement.querySelectorAll('.nx-setting-emoji').forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}
function nxChosenEmoji(){const x=document.querySelector('.nx-setting-emoji.selected');return x?NX_SETTING_ICONS[Number(x.dataset.nxIc)]:null}
function nxRenderArchive(){const host=document.getElementById('nx-archive-content');if(!host)return;const all=defs.filter(d=>groups.some(g=>g.tools.includes(d[0])));const archived=archivedModuleIds();host.innerHTML=`<p class="nx-hint">${all.length-archived.length} actifs · ${archived.length} archivés</p><input class="field" type="search" id="nx-archive-search" placeholder="Rechercher un module…" oninput="nxFilterArchive()"><div class="nx-tabs"><button data-filter="all" class="selected" onclick="nxArchiveFilter='all';nxFilterArchive()">Tous</button><button data-filter="active" onclick="nxArchiveFilter='active';nxFilterArchive()">Actifs</button><button data-filter="archived" onclick="nxArchiveFilter='archived';nxFilterArchive()">Archivés</button></div><div id="nx-archive-list"></div>`;nxFilterArchive()}
let nxArchiveFilter='all';
function nxFilterArchive(){const host=document.getElementById('nx-archive-list');if(!host)return;const q=(document.getElementById('nx-archive-search')?.value||'').toLowerCase(),archived=archivedModuleIds();document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===nxArchiveFilter));host.innerHTML=defs.filter(d=>groups.some(g=>g.tools.includes(d[0]))).filter(d=>d[2].toLowerCase().includes(q)&&(nxArchiveFilter==='all'||(nxArchiveFilter==='archived')===archived.includes(d[0]))).sort((a,b)=>a[2].localeCompare(b[2],'fr')).map(d=>`<div class="nx-item-row"><span class="nx-module-symbol">${nxModuleIcon(d[0],d[1])}</span><span class="nx-item-main"><strong>${esc(d[2])}</strong><small>${esc(nxGroupForModule(d[0])?.title||'Autres')}</small></span><button class="btn nx-small" onclick="nxToggleArchive('${d[0]}')">${archived.includes(d[0])?'Réactiver':'Archiver'}</button></div>`).join('')||'<p class="nx-hint">Aucun module trouvé.</p>'}
function nxToggleArchive(id){const archived=new Set(archivedModuleIds());if(archived.has(id)){archived.delete(id);put('archivedModuleIds',[...archived]);nxRenderArchive();toast('Module réactivé');return}const name=defs.find(d=>d[0]===id)?.[2]||'ce module';nxModal(`<h3>Archiver ${esc(name)} ?</h3><p>Le module sera masqué de NEXO. Toutes ses données seront conservées.</p><div class="nx-btn-row"><button class="btn" onclick="nxCloseModal()">Annuler</button><button class="btn primary" onclick="nxCommitArchive('${id}')">Archiver</button></div>`)}
function nxCommitArchive(id){const set=new Set(archivedModuleIds());set.add(id);put('archivedModuleIds',[...set]);nxCloseModal();nxRenderArchive();toast('Module archivé')}
function nxGroupForModule(id){const orig=groups.find(g=>g.tools.includes(id));const assigned=moduleGroupAssignments()[id];return allModuleGroups().find(g=>g.id===(assigned||orig?.id))||orig}
function nxRenderCategories(){const host=document.getElementById('nx-categories-list');if(!host)return;host.innerHTML=(moduleCategoryDraft||[]).map(id=>{const g=allModuleGroups().find(x=>x.id===id);if(!g)return '';return `<div class="nx-item-row nx-draggable" data-cid="${esc(id)}"><span class="nx-module-symbol">${g.icon||'📁'}</span><span class="nx-item-main"><strong>${esc(g.title)}</strong></span><button class="nx-pencil" aria-label="Modifier ${esc(g.title)}" onclick="nxEditCategory('${id}')">✎</button><button class="nx-drag-handle" aria-label="Déplacer ${esc(g.title)}" type="button">☰</button></div>`}).join('');nxBindCategoryDrag()}
function nxCreateCategory(){const el=document.getElementById('nx-new-cat');const title=el?.value.trim();if(!title)return toast('Indique un nom');if(allModuleGroups().some(g=>g.title.toLocaleLowerCase('fr')===title.toLocaleLowerCase('fr')))return toast('Catégorie déjà existante');const id='custom-'+Date.now().toString(36);put('customModuleGroups',[...customModuleGroups(),{id,title,icon:'📁',desc:'Catégorie personnalisée',tools:[],tone:'blue'}]);moduleCategoryDraft.push(id);el.value='';nxRenderCategories();toast('Catégorie créée')}
function nxEditCategory(id){const g=allModuleGroups().find(x=>x.id===id);if(!g)return;nxModal(`<h3>Modifier la catégorie</h3><label class="nx-field-label">Nom<input class="field" maxlength="45" id="nx-edit-cat-name" value="${esc(g.title)}"></label><label class="nx-field-label">Icône</label>${nxEmojiPicker(g.icon)}<div class="nx-btn-row"><button class="btn" onclick="nxCloseModal()">Annuler</button><button class="btn primary" onclick="nxSaveCategory('${id}')">Enregistrer</button></div>`)}
function nxSaveCategory(id){const g=allModuleGroups().find(x=>x.id===id),title=document.getElementById('nx-edit-cat-name')?.value.trim(),icon=nxChosenEmoji()||g.icon;if(!title)return toast('Nom requis');if(allModuleGroups().some(x=>x.id!==id&&x.title.toLocaleLowerCase('fr')===title.toLocaleLowerCase('fr')))return toast('Ce nom existe déjà');if(id.startsWith('custom-'))put('customModuleGroups',customModuleGroups().map(x=>x.id===id?{...x,title}:x));else{const names=get('nxCategoryNames',{});names[id]=title;put('nxCategoryNames',names)}const icons=get('moduleCategoryIcons',{});icons[id]=icon;put('moduleCategoryIcons',icons);nxCloseModal();nxRenderCategories();toast('Catégorie modifiée')}
function nxBindCategoryDrag(){const host=document.getElementById('nx-categories-list');host.querySelectorAll('.nx-drag-handle').forEach(handle=>{handle.addEventListener('pointerdown',e=>{const row=handle.closest('.nx-draggable');if(!row)return;nxCategoryDrag={id:row.dataset.cid,handle,pointer:e.pointerId};handle.setPointerCapture(e.pointerId);row.classList.add('nx-dragging');e.preventDefault()});handle.addEventListener('pointermove',e=>{if(!nxCategoryDrag||nxCategoryDrag.handle!==handle)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.nx-draggable');if(!target||target.dataset.cid===nxCategoryDrag.id)return;const a=moduleCategoryDraft.indexOf(nxCategoryDrag.id),b=moduleCategoryDraft.indexOf(target.dataset.cid);if(a<0||b<0)return;moduleCategoryDraft.splice(a,1);moduleCategoryDraft.splice(b,0,nxCategoryDrag.id);host.insertBefore(handle.closest('.nx-draggable'),a<b?target.nextSibling:target)});const done=()=>{if(!nxCategoryDrag||nxCategoryDrag.handle!==handle)return;handle.closest('.nx-draggable')?.classList.remove('nx-dragging');nxCategoryDrag=null};handle.addEventListener('pointerup',done);handle.addEventListener('pointercancel',done)})}
function nxSaveCategoryOrder(){put('moduleCategoryOrder',moduleCategoryDraft.slice());toast('Ordre des catégories enregistré')}
function nxDefaultCategoryOrder(){moduleCategoryDraft=allModuleGroups().map(g=>g.id);nxRenderCategories()}
function nxExpandAllCategories(){const all=allModuleGroups().map(g=>g.id);nxSettingsExpanded=nxSettingsExpanded.size===all.length?new Set():new Set(all);nxRenderSettingsModules()}
function nxRenderSettingsModules(){const host=document.getElementById('nx-settings-module-list');if(!host)return;const q=nxSettingsSearch.toLocaleLowerCase('fr');host.innerHTML=orderedGroups().map(g=>{const found=defs.filter(d=>groups.some(x=>x.tools.includes(d[0]))&&nxGroupForModule(d[0])?.id===g.id&&d[2].toLocaleLowerCase('fr').includes(q)).sort((a,b)=>a[2].localeCompare(b[2],'fr'));if(q&&!found.length)return '';const open=!!q||nxSettingsExpanded.has(g.id);return `<section class="nx-module-group"><button class="nx-group-header" onclick="nxToggleSettingsGroup('${g.id}')"><span>${g.icon||'📁'} ${esc(g.title)}</span><span>${found.length} ${open?'⌃':'⌄'}</span></button>${open?found.map(d=>`<div class="nx-item-row"><span class="nx-module-symbol">${nxModuleIcon(d[0],d[1])}</span><span class="nx-item-main"><strong>${esc(d[2])}</strong></span><button class="nx-pencil" onclick="nxEditSettingsModule('${d[0]}')" aria-label="Modifier ${esc(d[2])}">✎</button></div>`).join(''):''}</section>`}).join('')||'<p class="nx-hint">Aucun module trouvé.</p>'}
function nxToggleSettingsGroup(id){nxSettingsExpanded.has(id)?nxSettingsExpanded.delete(id):nxSettingsExpanded.add(id);nxRenderSettingsModules()}
function nxEditSettingsModule(id){const d=defs.find(x=>x[0]===id);if(!d)return;const group=nxGroupForModule(id);nxModal(`<h3>Personnaliser le module</h3><div class="nx-module-edit-name"><span>${nxModuleIcon(id,d[1])}</span><strong>${esc(d[2])}</strong></div><label class="nx-field-label">Catégorie<select class="field" id="nx-edit-module-cat">${allModuleGroups().map(g=>`<option value="${g.id}" ${g.id===group?.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><label class="nx-field-label">Icône</label>${nxEmojiPicker(nxModuleIcon(id,d[1]))}<div class="nx-btn-row"><button class="btn" onclick="nxCloseModal()">Annuler</button><button class="btn primary" onclick="nxSaveSettingsModule('${id}')">Enregistrer</button></div>`)}
function nxSaveSettingsModule(id){const d=defs.find(x=>x[0]===id),cat=document.getElementById('nx-edit-module-cat').value,icon=nxChosenEmoji();if(!d)return;const a={...moduleGroupAssignments()};a[id]=cat;put('moduleGroupAssignments',a);if(icon){const icons=get('nxModuleIcons',{});icons[id]=icon;put('nxModuleIcons',icons)}nxCloseModal();nxRenderSettingsModules();toast('Module personnalisé')}
function nxLastBackupLabel(){const d=get('nxLastBackup','');if(!d)return 'Aucune sauvegarde enregistrée';const t=new Date(d);return isNaN(t)?'Aucune sauvegarde enregistrée':t.toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}
function nxFmtSize(n){return n>=1048576?(n/1048576).toLocaleString('fr-FR',{maximumFractionDigits:2})+' Mo':n>=1024?(n/1024).toLocaleString('fr-FR',{maximumFractionDigits:1})+' Ko':Math.round(n)+' o'}
const NX_STORAGE_RULES=[
 [/^(expense|incomeEntries|incomeFold|removedExpense)/i,'expenses'],[/^savings/i,'savings'],
 [/^garage(Vehicles|Records|Plans)/i,'garage'],[/^moto_/i,'moto'],
 [/^(nexoRecipes|nexoClassicRecipes)/i,'recipes'],[/^nexoLoyalty/i,'loyalty'],[/^nexoHealth/i,'healthcard'],
 [/^nxQr/i,'qrcode'],[/^tasks$/i,'todo'],[/^notes$/i,'notes'],[/^shopping$/i,'shopping'],[/^nutrition/i,'nutrition'],
 [/^sportSessions/i,'sport'],[/^nexoParking/i,'parking'],[/^nexoFx/i,'fx'],[/^nxWorld/i,'worldclock'],
 [/^nxSound/i,'sonometer'],[/^travel_v10$/i,'travel'],[/^nxLife/i,'lifetimes']
];
const NX_STORAGE_PLAIN_KEYS={'nexo_lifetime_v1':'lifetimes','nexoMindsetDailyStatus_v1':'mindset'};
function nxApproxSize(v,depth=0){if(v==null)return 0;if(typeof v==='string')return v.length;if(typeof v==='number'||typeof v==='boolean')return 8;if(v instanceof Blob)return v.size;if(v instanceof ArrayBuffer||ArrayBuffer.isView(v))return v.byteLength;if(depth>6)return 0;if(Array.isArray(v))return v.reduce((t,x)=>t+nxApproxSize(x,depth+1),0);if(typeof v==='object')return Object.keys(v).reduce((t,k)=>t+k.length+nxApproxSize(v[k],depth+1),0);return 0}
async function nxIdbSize(name){
 try{
  if(!indexedDB.databases)return 0;
  const list=await indexedDB.databases();if(!list.some(d=>d.name===name))return 0;
  const db=await new Promise((ok,ko)=>{const r=indexedDB.open(name);r.onupgradeneeded=e=>{try{e.target.transaction.abort()}catch(_){}};r.onsuccess=()=>ok(r.result);r.onerror=()=>ko(r.error);r.onblocked=()=>ko(Error('bloqué'))});
  try{
   const stores=[...db.objectStoreNames];if(!stores.length)return 0;
   const tx=db.transaction(stores,'readonly');let total=0;
   await Promise.all(stores.map(st=>new Promise((ok,ko)=>{const r=tx.objectStore(st).openCursor();r.onsuccess=()=>{const c=r.result;if(!c)return ok();total+=nxApproxSize(c.value);c.continue()};r.onerror=()=>ko(r.error)})));
   return total;
  }finally{db.close()}
 }catch(e){return 0}
}
async function nxEstimateModuleBytes(){
 const arr=defs.filter(d=>groups.some(g=>g.tools.includes(d[0]))).map(d=>({id:d[0],name:d[2],bytes:0,icon:nxModuleIcon(d[0],d[1])}));
 const byId=Object.fromEntries(arr.map(m=>[m.id,m]));
 const unassigned={id:'other',name:'Données communes / autres',bytes:0,icon:'📦'};
 const add=(id,bytes)=>{(byId[id]||unassigned).bytes+=bytes};
 let legacyTravel=0;
 for(let i=0;i<localStorage.length;i++){
  const key=localStorage.key(i);if(!key)continue;
  const plain=NX_STORAGE_PLAIN_KEYS[key];
  if(!plain&&!key.startsWith('tb_'))continue;
  const bytes=new Blob([key,localStorage.getItem(key)||'']).size;
  if(plain){add(plain,bytes);continue}
  const short=key.slice(3);
  if(short==='travel_v10'){legacyTravel+=bytes;continue}
  const rule=NX_STORAGE_RULES.find(r=>r[0].test(short));
  if(rule){add(rule[1],bytes);continue}
  const matches=arr.filter(m=>key.toLowerCase().includes(m.id.toLowerCase())&&m.id.length>=4);
  if(matches.length===1)matches[0].bytes+=bytes;else unassigned.bytes+=bytes;
 }
 let trips=0;try{const t=await nxTravelRead();if(Array.isArray(t)&&t.length)trips=new Blob([JSON.stringify(t)]).size}catch(e){}
 add('travel',trips||legacyTravel);
 add('vault',await nxIdbSize('nexo-vault-v1'));
 add('password-manager',await nxIdbSize('nexo-password-manager-v1'));
 return [...arr,unassigned];
}
async function nxRenderStorageTab(){const host=document.getElementById('nx-storage-tab');if(!host)return;document.querySelectorAll('.nx-tabs button').forEach((x,i)=>x.classList.toggle('selected',i===(nxSettingsTab==='modules'?0:1)));if(nxSettingsTab==='backup'){host.innerHTML=`<div class="nx-storage-actions"><button class="btn primary nx-full" onclick="backupAllData()">Exporter une sauvegarde</button><button class="btn nx-full" onclick="restoreAllData()">Restaurer une sauvegarde</button><p class="nx-hint">Sauvegarde JSON complète des données prises en charge. Les documents du coffre-fort chiffré nécessitent leur export séparé.</p></div>`;return}const options=[['sizeDesc','Poids décroissant'],['sizeAsc','Poids croissant'],['nameAsc','Nom A → Z'],['nameDesc','Nom Z → A']];host.innerHTML='<p class="nx-hint">Calcul en cours…</p>';const raw=await nxEstimateModuleBytes();if(document.getElementById('nx-storage-tab')!==host)return;const items=raw.sort((a,b)=>nxSettingsSort==='nameAsc'?a.name.localeCompare(b.name,'fr'):nxSettingsSort==='nameDesc'?b.name.localeCompare(a.name,'fr'):nxSettingsSort==='sizeAsc'?a.bytes-b.bytes:b.bytes-a.bytes);const max=Math.max(1,...items.map(m=>m.bytes));host.innerHTML=`<select class="field nx-sort" onchange="nxSettingsSort=this.value;nxRenderStorageTab()">${options.map(([v,l])=>`<option value="${v}" ${v===nxSettingsSort?'selected':''}>${l}</option>`).join('')}</select>${items.map(m=>`<div class="nx-storage-module"><div><span>${esc(m.name)}</span><strong>${nxFmtSize(m.bytes)}</strong></div><div class="nx-bar"><span style="width:${m.bytes/max*100}%"></span></div></div>`).join('')}<p class="nx-hint">Mesure indicative des données locales de chaque module (y compris voyages, coffre-fort et mots de passe). « Données communes / autres » regroupe les réglages et ce qui ne peut pas être rattaché à un module.</p>`}
const nxOriginalAllGroups=allModuleGroups;
allModuleGroups=function(){const names=get('nxCategoryNames',{});return nxOriginalAllGroups().map(g=>({...g,title:names[g.id]||g.title}))};
const nxOriginalGen2Home=gen2Home;
gen2Home=function(...args){const r=nxOriginalGen2Home.apply(this,args);nxRenderHomeWelcome();return r};
function nxRenderHomeWelcome(){document.getElementById('nx-welcome-home')?.remove();if(!get('nxWelcomeEnabled',false))return;const msg=get('nxWelcomeText','');if(!msg)return;const header=document.querySelector('header');if(!header)return;const el=document.createElement('p');el.id='nx-welcome-home';el.textContent=msg;header.append(el)}
nxApplyAccent();
